{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 청년 기본 조례상 청년정책 기본계획 수립 주기(몇 년마다)",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 청년 기본 조례 제6조제1항에 따르면 시장은 청년정책에 관한 기본계획을 5년마다 수립하고 이를 시행하여야 한다.",
          "b_ids": "청년:제6조제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 청년 기본 조례상 시행계획·추진실적 보고 주기와 보고 대상",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "시장은 제6조에 따라 수립된 기본계획에 따른 연도별 시행계획을 수립·시행하여야 한다(제7조제1항).",
          "b_ids": "청년:제7조제1항"
        },
        {
          "a_text": "시장은 제1항에 따라 수립한 시행계획과 전년도 시행계획에 따른 추진실적을 제9조에 따른 청년정책조정위원회에 매년 보고하여야 한다(제7조제2항).",
          "b_ids": "청년:제7조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
